L000381	\section{\label{sec:derivation}Derivation of Charge and Current Response Coefficients}
L000382	
L000383	In this section, we derive the static charge response coefficient $\zeta^{\alpha_1 \alpha_2}(\mathbf{G}; \omega_0)$ and the static current
L000384	response coefficient $\sigma^{\beta \alpha_1 \alpha_2}(\mathbf{G}; \omega_0)$ within the independent-particle approximation, explicitly accounting for spatial inhomogeneity.
L000385	The derivation proceeds via a perturbative expansion of the reduced density matrix in powers of the external electric field,
L000386	following a methodology similar to that used for computing optical conductivity in the case of uniform photocurrents~\Scite{peres2017,peres2018}.
L000387	
L000388	We work in the length gauge \Scite{peres2017,peres2018}, where the light–matter interaction is described by a dipole coupling term $e\,\mathbf{E}(t) \cdot \mathbf{r}$.
L000389	Here, $e>0$ is the elementary charge, and $\mathbf{E}(t)$ is the time-dependent electric field of the incident light.
L000390	We consider normally incident, monochromatic light with arbitrary polarization:
L000391	\begin{equation}
L000392	    \mathbf{E}(t) = \mathbf{E}_0(\omega_0) \, e^{-i \omega_0 t} + \mathbf{E}_0(-\omega_0) \, e^{i \omega_0 t},\;\;\; \mathbf{E}_0(-\omega_0) = \mathbf{E}^{*}_0(\omega_0)\nonumber,
L000393	\end{equation}
L000394	ensuring $\mathbf{E}(t)$ is real-valued.
L000395	
L000396	The system Hamiltonian in second-quantized form reads:
L000397	\begin{equation}
L000398	\label{eq:full_hamiltonian}
L000399	    \hat{H}(t) = \sum_{s} \int \left[ \mathrm{d}\mathbf{k} \right] \, \epsilon_{\mathbf{k} s}
L000400	    c^{\dagger}_{\mathbf{k} s} c_{\mathbf{k} s} + i e \mathbf{E}(t) \cdot
L000401	    \sum_{s,s^{\prime}} \int \left[ \mathrm{d}\mathbf{k} \right] \,
L000402	    c^{\dagger}_{\mathbf{k} s} \mathbf{D}_{\mathbf{k} s s^{\prime}} c_{\mathbf{k} s^{\prime}},
L000403	\end{equation}
L000404	where
L000405	\begin{itemize}
L000406	    \item $s,s^{\prime}$ are band indices (including both conduction and valence bands),
L000407	    \item $\int \left[ \mathrm{d}\mathbf{k} \right] \equiv \int_{\text{MBZ}} \frac{\mathrm{d}\mathbf{k}}{(2\pi)^2}$ is the integral over the moiré Brillouin zone,
L000408	    \item $\epsilon_{\mathbf{k} s}$ is the band dispersion,
L000409	    \item $c^{\dagger}_{\mathbf{k} s}$ and $c_{\mathbf{k} s}$ are creation and annihilation operators for Bloch states $\left| \psi_{\mathbf{k} s} \right\rangle$.
L000410	\end{itemize}
L000411	These operators obey the canonical anticommutation relation:
L000412	\begin{equation}
L000413	    \{ c_{\mathbf{k} s}, c^{\dagger}_{\mathbf{k}^{\prime} s^{\prime}} \} = (2\pi)^2 \delta_{s s^{\prime}} \delta(\mathbf{k}-\mathbf{k}^{\prime}). \nonumber
L000414	\end{equation}
L000415	The covariant derivative $\mathbf{D}_{\mathbf{k} s s^{\prime}}$ \Scite{peres2017,peres2018} arises from the position operator in the Bloch representation and is defined as:
L000416	\begin{equation}
L000417	\label{eq:codrv_def}
L000418	    \mathrm{D}^{\beta}_{\mathbf{k} s s^{\prime}} \equiv \delta_{s s^{\prime}} \nabla^{\beta}_{\mathbf{k}} - i \xi^{\beta}_{\mathbf{k} s s^{\prime}}, \;\;\;
L000419	    \xi^{\beta}_{\mathbf{k} s s^{\prime}} \equiv i \left\langle u_{\mathbf{k} s} \right| \nabla^{\beta}_{\mathbf{k}} \left| u_{\mathbf{k} s^{\prime}} \right\rangle,
L000420	\end{equation}
L000421	where $\xi^{\beta}_{\mathbf{k} s s^{\prime}}$ is the Berry connection. The first term of Eq.~(\ref{eq:full_hamiltonian})
L000422	describes the unperturbed band structure, while the second term captures the interaction with the optical field.
L000423	
L000424	We focus on the response of the Fourier components of the charge and current density operators at wavevector $\mathbf{G}$ in the moir\'e reciprocal lattice.
L000425	These operators are denoted $\hat{\rho}_{\mathbf{G}}$ and $\hat{\mathbf{j}}_{\mathbf{G}}$, respectively. Their second-quantized forms are given by
L000426	\begin{equation}
L000427	\label{eq:charge_operator}
L000428	    \hat{\rho}_{\mathbf{G}} = -e \sum_{s,s^{\prime}} \int \left[ \mathrm{d}\mathbf{k} \right]\,
L000429	    F^{\mathbf{G}}_{\mathbf{k} s s^{\prime}} \, c^{\dagger}_{\mathbf{k} s}  c_{\mathbf{k} s^{\prime}},
L000430	\end{equation}
L000431	
L000432	\begin{equation}
L000433	\label{eq:current_operator}
L000434	    \hat{\mathrm{j}}^{\beta}_{\mathbf{G}} = -e \sum_{s,s^{\prime}} \int \left[ \mathrm{d}\mathbf{k} \right]
L000435	     \, \mathrm{M}^{\beta}_{\mathbf{k} s s^{\prime}}(\mathbf{G}) \, c^{\dagger}_{\mathbf{k} s} c_{\mathbf{k} s^{\prime}},
L000436	\end{equation}
L000437	where $F^{\mathbf{G}}_{\mathbf{k} s s^{\prime}} = \left\langle u_{\mathbf{k} s} \middle|
L000438	u_{\mathbf{k}+\mathbf{G} s^{\prime}} \right\rangle$ is the overlap between the periodic parts of two Bloch states,
L000439	and $\mathrm{M}^{\beta}_{\mathbf{k} s s^{\prime}}(\mathbf{G})$ is defined as \Scite{bradlyn2024uniformity}:
L000440	\begin{equation}
L000441	    \mathrm{M}^{\beta}_{\mathbf{k} s s^{\prime}}(\mathbf{G}) =
L000442	    \hbar^{-1} \int^1_0 \mathrm{d}\lambda \, \left\langle u_{\mathbf{k} s} \right|
L000443	    [ \nabla^{\beta}_{\mathbf{k}} \mathcal{H}(\mathbf{k}) ]_{\mathbf{k} \to \mathbf{k}+(1-\lambda)\mathbf{G}} \left| u_{\mathbf{k}+\mathbf{G} s^{\prime}} \right\rangle.
L000444	\end{equation}
L000445	Here, $\mathcal{H}(\mathbf{k}) = e^{-i \mathbf{k} \cdot \hat{\mathbf{r}}} \mathcal{H} e^{i \mathbf{k} \cdot \hat{\mathbf{r}}}$ is the first-quantized single-particle Hamiltonian as a function of $\mathbf{k}$.
L000446	As a consistency check, the $\mathbf{G}=\mathbf{0}$ component of Eq.~(\ref{eq:current_operator}) recovers the conventional current operator \Scite{peres2017}:
L000447	\begin{equation}
L000448	    \hat{\mathrm{j}}^{\beta}_{\mathbf{G}=\mathbf{0}} = -e \sum_{s,s^{\prime}} \int \left[ \mathrm{d}\mathbf{k} \right]
L000449	     \, \left\langle u_{\mathbf{k} s} \right| \mathrm{v}^{\beta}(\mathbf{k})
L000450	     \left| u_{\mathbf{k} s^{\prime}} \right\rangle
L000451	    \, c^{\dagger}_{\mathbf{k} s} c_{\mathbf{k} s^{\prime}},
L000452	\end{equation}
L000453	where $\mathrm{v}^{\beta}\left( \mathbf{k} \right) \equiv \hbar^{-1} \nabla^{\beta}_{\mathbf{k}} \mathcal{H}(\mathbf{k})$ is the velocity operator.
L000454	
L000455	The evolution of the many-body state [described by the density operator $\hat{P}(t)$] under a time-dependent electric field is governed by the Liouville–von Neumann equation:
L000456	\begin{equation}
L000457	\label{eq:liouville_von_neumann}
L000458	    i \hbar \, \frac{\mathrm{d} \hat{P}(t)}{\mathrm{d} t} = [ \hat{H}(t), \hat{P}(t) ].
L000459	\end{equation}
L000460	To compute the optical response, we focus on the time-dependent expectation values of the Fourier components of the charge and current density operators,
L000461	$\hat{\rho}_{\mathbf{G}}$ and $\hat{\mathbf{j}}_{\mathbf{G}}$ [Eqs.~(\ref{eq:charge_operator}) and~(\ref{eq:current_operator})].
L000462	Using Eqs.~(\ref{eq:liouville_von_neumann}), we obtain:
L000463	\begin{equation}
L000464	\label{eq:charge_response}
L000465	    \left\langle \hat{\rho}_{\mathbf{G}} \right\rangle (t) \equiv
L000466	    \mathrm{Tr} \left\{ \hat{\rho}_{\mathbf{G}} \hat{P}(t) \right\}
L000467	    = -e  \sum_{s,s^{\prime}} \int \left[ \mathrm{d}\mathbf{k} \right] \,
L000468	    F^{\mathbf{G}}_{\mathbf{k} s s^{\prime}} \, P_{\mathbf{k} s^{\prime} s}(t),
L000469	\end{equation}
L000470	\begin{equation}
L000471	\label{eq:current_response}
L000472	    \left\langle \hat{\mathrm{j}}^{\beta}_{\mathbf{G}} \right\rangle (t)
L000473	    \equiv \mathrm{Tr} \left\{ \hat{\mathrm{j}}^{\beta}_{\mathbf{G}} \hat{P}(t) \right\}
L000474	    = -e \sum_{s,s^{\prime}} \int \left[ \mathrm{d}\mathbf{k} \right] \,
L000475	    \mathrm{M}^{\beta}_{\mathbf{k} s s^{\prime}}(\mathbf{G})
L000476	    \, P_{\mathbf{k} s^{\prime} s}(t),
L000477	\end{equation}
L000478	where we have introduced the reduced density matrix:
L000479	\begin{equation}
L000480	\label{eq:RDM_definition}
L000481	    P_{\mathbf{k} s s^{\prime}}(t) \equiv \mathrm{Tr} \left\{ c^{\dagger}_{\mathbf{k} s^{\prime}} \, c_{\mathbf{k} s} \hat{P}(t) \right\}.
L000482	\end{equation}
L000483	The dynamics of the charge and current responses are thus fully encoded in the time evolution of the reduced density matrix $P_{\mathbf{k}}(t)$.
L000484	To proceed, we derive its equation of motion by differentiating Eq.~(\ref{eq:RDM_definition}) and using Eq.~(\ref{eq:liouville_von_neumann}). This yields:
L000485	\begin{equation}
L000486	\label{eq:rdm_eom}
L000487	    (i \hbar \, \partial_{t} - \Delta \epsilon_{\mathbf{k} s s^{\prime}})
L000488	    P_{\mathbf{k} s s^{\prime}}(t) = i e \mathbf{E}(t) \cdot [ \mathbf{D}_{\mathbf{k}}, P_{\mathbf{k}}(t) ]_{s s^{\prime}},
L000489	\end{equation}
L000490	where $\Delta \epsilon_{\mathbf{k} s s^{\prime}} \equiv \epsilon_{\mathbf{k} s} - \epsilon_{\mathbf{k} s^{\prime}}$, and
L000491	$[\mathbf{D}_{\mathbf{k}}, P_{\mathbf{k}} ] = \mathbf{D}_{\mathbf{k}} P_{\mathbf{k}} - P_{\mathbf{k}} \mathbf{D}_{\mathbf{k}}$ denotes the commutator in band space.
L000492	Using the definition of the covariant derivative $\mathbf{D}_{\mathbf{k} s s^{\prime}}$ [Eq.~(\ref{eq:codrv_def})], its commutator with a generic
L000493	operator $\mathcal{O}_{\mathbf{k} s s^{\prime}}$ can be calculated as:
L000494	\begin{equation}
L000495	\label{eq:codrv_commutator}
L000496	    [\mathrm{D}^{\beta}_{\mathbf{k}}, \mathcal{O}_{\mathbf{k}}]_{s s^{\prime}} = \nabla^{\beta}_{\mathbf{k}}
L000497	    \mathcal{O}_{\mathbf{k} s s^{\prime}} - i [\xi^{\beta}_{\mathbf{k}}, \mathcal{O}_{\mathbf{k}}]_{s s^{\prime}}.
L000498	\end{equation}
L000499	In deriving Eq.~(\ref{eq:rdm_eom}), we have used the decomposition of the Hamiltonian in Eq.~(\ref{eq:full_hamiltonian}),
L000500	separating the unperturbed band structure and the light-matter interaction.
L000501	
L000502	To solve the equation of motion Eq.~(\ref{eq:rdm_eom}), we assume that the system is initially in equilibrium at $t \to -\infty$,
L000503	where the reduced density matrix takes the form $P_{\mathbf{k} s s^{\prime}}(t\to-\infty) = f_{\mathbf{k}s} \delta_{s s^{\prime}}$, with
L000504	$f_{\mathbf{k}s}$ being the Fermi–Dirac distribution. For analytic convenience, we work in frequency space, where Eq.~(\ref{eq:rdm_eom}) becomes:
L000505	\begin{equation}
L000506	\label{eq:rdm_eom_freq}
L000507	    (\hbar\omega-\Delta\epsilon_{\mathbf{k} s s^{\prime}})P_{\mathbf{k} s s^{\prime}}(\omega) = ie \int [ \mathrm{d}\omega^{\prime} ] [ \mathrm{d}\omega^{\prime \prime} ] \,
L000508	    \mathrm{E}^{\beta}(\omega^{\prime}) [ \mathrm{D}^{\beta}_{\mathbf{k}}, P_{\mathbf{k}}(\omega^{\prime \prime})]_{s s^{\prime}} (2\pi)\, \delta(\omega - \omega^{\prime} - \omega^{\prime \prime}).
L000509	\end{equation}
L000510	Here, $\int [ \mathrm{d}\omega] \equiv \int_{-\infty}^{\infty} \frac{\mathrm{d}\omega}{2\pi}$, and summation over repeated Cartesian indices (e.g., $\beta$) is implied.
L000511	We solve Eq.~(\ref{eq:rdm_eom_freq}) perturbatively, order by order in the electric field, using a recursive approach.
L000512	The $n^{\mathrm{th}}$-order contribution to the reduced density matrix in frequency space is written as
L000513	\begin{eqnarray}
L000514	\label{eq:nth_RDM}
L000515	    P^{(n)}_{\mathbf{k} s s^{\prime}}(\omega) &&= (ie)^n \int \left[ \mathrm{d}\omega_1 \right]
L000516	    ... \left[ \mathrm{d}\omega_n \right] \, \mathrm{E}^{\alpha_1}(\omega_1)...\mathrm{E}^{\alpha_n}(\omega_n) \nonumber\\
L000517	    &&\times (2\pi)\, \delta(\omega - \omega_1 - ... -\omega_n) \nonumber\\
L000518	    &&\times \mathcal{P}^{\alpha_1 ... \alpha_n}_{\mathbf{k} s s^{\prime}}(\omega_1,...,\omega_n),
L000519	\end{eqnarray}
L000520	where $\mathcal{P}^{\alpha_1 ... \alpha_n}_{\mathbf{k} s s^{\prime}}(\omega_1,...,\omega_n)$ is a kernel determined recursively.
L000521	The zeroth-order kernel simply corresponds to the equilibrium distribution:
L000522	\begin{equation}
L000523	\label{eq:0th_kernel}
L000524	    \mathcal{P}^{[0]}_{\mathbf{k} s s^{\prime}} = f_{\mathbf{k} s} \delta_{s s^{\prime}},
L000525	\end{equation}
L000526	where $f_{\mathbf{k} s} = \frac{1}{e^{(\epsilon_{\mathbf{k} s} - \mu)/ (k_B T)} + 1}$. Note that the superscript $[0]$ labels the kernel,
L000527	not the frequency-space density matrix $P^{(n=0)}_{\mathbf{k} s s^{\prime}}(\omega)$. The first-order kernel is given by:
L000528	\begin{equation}
L000529	\label{eq:1st_kernel}
L000530	\mathcal{P}^{\alpha_1}_{\mathbf{k}}(\omega_1) =
L000531	\frac{1}{\hbar \omega_1 - \Delta \epsilon_{\mathbf{k}}} \circ
L000532	[ \mathrm{D}^{\alpha_1}_{\mathbf{k}}, \mathcal{P}^{[0]}_{\mathbf{k}}],
L000533	\end{equation}
L000534	while the second-order kernel is given by
L000535	\begin{eqnarray}
L000536	\label{eq:2nd_kernel}
L000537	\mathcal{P}^{\alpha_1 \alpha_2}_{\mathbf{k}}(\omega_1, \omega_2) =
L000538	\frac{1}{\hbar \omega_1 + \hbar \omega_2 - \Delta \epsilon_{\mathbf{k}}} \circ
L000539	[ \mathrm{D}^{\alpha_2}_{\mathbf{k}}, \mathcal{P}^{\alpha_1}_{\mathbf{k}}(\omega_1)].
L000540	\end{eqnarray}
L000541	Here, $\circ$ denotes the Hadamard (element-wise) product of matrices in band indices: $(A\circ B)_{s s^{\prime}} \equiv A_{s s^{\prime}} B_{s s^{\prime}}$.
L000542	In this work, we are primarily interested in the second-order response. Specifically, we compute the second-order reduced density matrix as defined by Eq.~(\ref{eq:nth_RDM}) for $n=2$,
L000543	using Eqs.~(\ref{eq:0th_kernel}),~(\ref{eq:1st_kernel}) and~(\ref{eq:2nd_kernel}).
L000544	
L000545	Finally, we obtain the nonlinear response coefficients by substituting the second-order reduced density matrix [Eq.~(\ref{eq:nth_RDM}) with $n=2$] into
L000546	the expressions for the charge and current responses, Eqs.~(\ref{eq:charge_response}) and~(\ref{eq:current_response}).
L000547	Retaining only the zero-frequency (DC) component of the response, we derive the second-order charge and current response tensors,
L000548	$\zeta^{\alpha_1 \alpha_2}(\mathbf{G}; \omega_0)$ and $\sigma^{\beta \alpha_1 \alpha_2}(\mathbf{G}; \omega_0)$, respectively:
L000549	\begin{eqnarray}
L000550	\label{eq:zeta_expression}
L000551	    \zeta^{\alpha_1 \alpha_2}(\mathbf{G}; \omega_0) &&= e^3 \int \left[ \mathrm{d}\mathbf{k} \right] \sum_{s,s^{\prime}}
L000552	    F^{\mathbf{G}}_{\mathbf{k} s^{\prime} s} \frac{1}{2i\hbar\eta-\Delta\epsilon_{\mathbf{k} s s^{\prime}}} \left[ \mathrm{D}^{\alpha_2}_{\mathbf{k}},\frac{1}{\hbar\omega_0-\Delta\epsilon_{\mathbf{k}}+i\hbar\eta}
L000553	    \circ[\mathrm{D}^{\alpha_1}_{\mathbf{k}}, \mathcal{P}^{[0]}_{\mathbf{k}}] \right]_{s s^{\prime}} \nonumber\\
L000554	    &&+ (\alpha_1,\omega_0 \leftrightarrow \alpha_2,-\omega_0),
L000555	\end{eqnarray}
L000556	and
L000557	\begin{eqnarray}
L000558	\label{eq:sigma_expression}
L000559	    \sigma^{\beta \alpha_1 \alpha_2}(\mathbf{G}; \omega_0) &&= e^3 \int \left[ \mathrm{d}\mathbf{k} \right] \sum_{s,s^{\prime}}
L000560	    M^{\beta}_{\mathbf{k} s^{\prime} s}(\mathbf{G}) \frac{1}{2i\hbar\eta-\Delta\epsilon_{\mathbf{k} s s^{\prime}}} \left[ \mathrm{D}^{\alpha_2}_{\mathbf{k}},\frac{1}{\hbar\omega_0-\Delta\epsilon_{\mathbf{k}}+i\hbar\eta}
L000561	    \circ[\mathrm{D}^{\alpha_1}_{\mathbf{k}}, \mathcal{P}^{[0]}_{\mathbf{k}}] \right]_{s s^{\prime}} \nonumber\\
L000562	    &&+ (\alpha_1,\omega_0 \leftrightarrow \alpha_2,-\omega_0).
L000563	\end{eqnarray}
L000564	Here, $\eta=0^+$ is an infinitesimal positive parameter introduced to regularize the frequency denominators.
L000565	Physically, this corresponds to adiabatically switching on the electric field in the distant past:
L000566	\begin{equation}
L000567	    \mathbf{E}(t) = e^{\eta t} \left[ \mathbf{E}_0(\omega_0) \, e^{-i \omega_0 t} + \mathbf{E}_0(-\omega_0) \, e^{i \omega_0 t} \right].
L000568	\end{equation}
L000569	The notation $(\alpha_1,\omega_0 \leftrightarrow \alpha_2,-\omega_0)$ indicates symmetrization under the exchange of indices and frequencies, ensuring that the response functions satisfy
L000570	\begin{equation}
L000571	    \zeta^{\alpha_1 \alpha_2}(\mathbf{G}; \omega_0) = \zeta^{\alpha_2 \alpha_1}(\mathbf{G}; -\omega_0),\;\;\;
L000572	\sigma^{\beta \alpha_1 \alpha_2}(\mathbf{G}; \omega_0) = \sigma^{\beta \alpha_2 \alpha_1}(\mathbf{G}; -\omega_0).
L000573	\end{equation}
L000574	
L000575	From Eq.~(\ref{eq:zeta_expression}), we observe that the terms with $s=s^{\prime}$ in the integrand contain a prefactor $\frac{1}{2i\hbar\eta}$,
L000576	indicating a divergence of order $\mathcal{O}(\eta^{-1})$. To isolate this divergent contribution, we simplify the nested commutator in
L000577	Eq.~(\ref{eq:zeta_expression}) using Eq.~(\ref{eq:codrv_commutator}), assuming a cold semiconductor for simplicity. This yields:
L000578	\begin{eqnarray}
L000579	\label{eq:commutator_simplify}
L000580	    &&\left[ \mathrm{D}^{\alpha_2}_{\mathbf{k}},\frac{1}{\hbar\omega_0-\Delta\epsilon_{\mathbf{k}}+i\hbar\eta} \circ[\mathrm{D}^{\alpha_1}_{\mathbf{k}}, \mathcal{P}^{[0]}_{\mathbf{k}}] \right]_{s s^{\prime}} \nonumber \\
L000581	    =&& \nabla^{\alpha_2}_{\mathbf{k}} \left( \frac{-i \xi^{\alpha_1}_{\mathbf{k} s s^{\prime}} \Delta f_{\mathbf{k} s^{\prime} s}}{\hbar \omega_0 - \Delta \epsilon_{\mathbf{k} s s^{\prime}} + i\hbar\eta} \right)
L000582	    - \sum_r \left( \frac{\xi^{\alpha_1}_{\mathbf{k} r s^{\prime}} \xi^{\alpha_2}_{\mathbf{k} s r} \Delta f_{\mathbf{k} s^{\prime} r}}{\hbar \omega_0 - \Delta \epsilon_{\mathbf{k} r s^{\prime}} + i\hbar\eta} -
L000583	    \frac{\xi^{\alpha_1}_{\mathbf{k} s r} \xi^{\alpha_2}_{\mathbf{k} r s^{\prime}} \Delta f_{\mathbf{k} r s}}{\hbar \omega_0 - \Delta \epsilon_{\mathbf{k} s r} + i\hbar\eta} \right).
L000584	\end{eqnarray}
L000585	Substituting Eq.~(\ref{eq:commutator_simplify}) into Eq.~(\ref{eq:zeta_expression}) and focusing on the $s=s^{\prime}$ terms, the response coefficient becomes:
L000586	\begin{equation}
L000587	    \zeta^{\alpha_1 \alpha_2}(\mathbf{G}; \omega_0) \to \frac{i e^3}{2\hbar\eta} \int \left[ \mathrm{d}\mathbf{k} \right] \sum_{r \ne s} \left( F^{\mathbf{G}}_{\mathbf{k} ss} - F^{\mathbf{G}}_{\mathbf{k} rr} \right)
L000588	    \frac{\xi^{\alpha_1}_{\mathbf{k} r s} \xi^{\alpha_2}_{\mathbf{k} s r} \Delta f_{\mathbf{k} s r}}{\hbar \omega_0 - \Delta \epsilon_{\mathbf{k} r s} + i\hbar\eta}
L000589	    + (\alpha_1,\omega_0 \leftrightarrow \alpha_2,-\omega_0).
L000590	\end{equation}
L000591	To extract the $\mathcal{O}(\eta^{-1})$ divergent part, we use the identity \Scite{gao2021intrinsic}:
L000592	\begin{equation}
L000593	    \frac{1}{\eta} \frac{1}{x+i \eta} = \frac{1}{\eta} \left[ \frac{\mathcal{P}}{x} - i \pi \delta(x) \right] - i\frac{\mathcal{P}}{x^2},
L000594	\end{equation}
L000595	where $\mathcal{P}$ denotes the Cauchy principal value. Keeping only the leading $\mathcal{O}(\eta^{-1})$ divergent contribution, we obtain the so-called accumulation response:
L000596	\begin{equation}
L000597	\label{eq:zeta_inj_expression}
L000598	    \zeta_{\mathrm{accum}}^{\alpha_1 \alpha_2}(\mathbf{G}; \omega_0) = \frac{\pi e^3}{\hbar\eta}
L000599	    \int \left[ \mathrm{d}\mathbf{k} \right] \sum_{r \ne s} \left( F^{\mathbf{G}}_{\mathbf{k} ss} - F^{\mathbf{G}}_{\mathbf{k} rr} \right)
L000600	    \, \xi^{\alpha_1}_{\mathbf{k} rs} \xi^{\alpha_2}_{\mathbf{k} sr} \Delta f_{\mathbf{k} sr} \delta(\hbar\omega_0 - \Delta\epsilon_{\mathbf{k} rs}).
L000601	\end{equation}
L000602	This expression corresponds precisely to Eq.~(\ref{eq:zeta_inj}) in the main text.
L000603	
L000604	
L000605	\section{\label{sec:time_derivative}Derivation of Eq.~(\ref{eq:CE_coef})}
L000606	
L000607	As noted in the main text [see footnote above Eq.~(\ref{eq:CE_coef})], the identity
L000608	\begin{equation}
L000609	\label{eq:CE_coef_sm}
L000610	    2\eta\,\zeta^{\alpha_1\alpha_2}(\mathbf{G};\omega_0) + i \mathrm{G}^{\beta} \sigma^{\beta \alpha_1\alpha_2}(\mathbf{G};\omega_0) = 0
L000611	\end{equation}
L000612	remains valid for finite $\eta$ if $\zeta^{\alpha_1\alpha_2}(\mathbf{G};\omega_0)$ is interpreted as the full response
L000613	[Eq.~(\ref{eq:zeta})], not just the accumulation part [Eq.~(\ref{eq:zeta_inj})]. We derive Eq.~(\ref{eq:CE_coef_sm}) below
L000614	to justify the generalized form of Eq.~(\ref{eq:CE_coef}), which is useful when $\eta$ is taken to be small but finite
L000615	in our numerical calculations. This result follows directly from the continuity equation. At the operator level, the
L000616	continuity equation reads:
L000617	\begin{equation}
L000618	\label{eq:continuity_equation_operator}
L000619	    \partial_t \hat{\rho}_{\mathbf{G}} + i \mathbf{G} \cdot \hat{\mathbf{j}}_{\mathbf{G}} = 0.
L000620	\end{equation}
L000621	In the Schr\"{o}dinger picture, operators such as $\hat{\rho}_{\mathbf{G}}$ [as defined in Eq.~(\ref{eq:charge_operator})] are time-independent, so
L000622	$\partial_t \hat{\rho}_{\mathbf{G}} = 0$ identically. Therefore, Eq.~(\ref{eq:continuity_equation_operator}) must be interpreted in the Heisenberg picture,
L000623	where operators evolve with time:
L000624	\begin{equation}
L000625	\label{eq:CE_H}
L000626	    \partial_t \hat{\rho}^{(\mathrm{H})}_{\mathbf{G}} + i \mathbf{G} \cdot \hat{\mathbf{j}}^{(\mathrm{H})}_{\mathbf{G}} = 0.
L000627	\end{equation}
L000628	Here, the superscript $(\mathrm{H})$ indicates operators in the Heisenberg picture; operators without it are understood to be in the Schr\"{o}dinger picture.
L000629	Taking the expectation value of both sides of Eq.~(\ref{eq:CE_H}), we obtain:
L000630	\begin{equation}
L000631	\label{eq:CE_expectation}
L000632	    \left\langle  \partial_t \hat{\rho}^{(\mathrm{H})}_{\mathbf{G}} \right\rangle +
L000633	    i \mathbf{G} \cdot \left\langle  \hat{\mathbf{j}}^{(\mathrm{H})}_{\mathbf{G}} \right\rangle = 0.
L000634	\end{equation}
L000635	
L000636	To evaluate the expectation value $\left\langle \partial_t \hat{\rho}^{(\mathrm{H})}_{\mathbf{G}} \right\rangle$, we proceed as follows:
L000637	\begin{eqnarray}
L000638	\label{eq:trace_trick}
L000639	    \left\langle \partial_t \hat{\rho}^{(\mathrm{H})}_{\mathbf{G}} \right\rangle && \equiv \mathrm{Tr}
L000640	    \left\{ \partial_t \hat{\rho}^{(\mathrm{H})}_{\mathbf{G}} \hat{P}^{(\mathrm{H})}(t) \right\} \nonumber\\
L000641	    &&= \frac{1}{i \hbar} \mathrm{Tr} \left\{ [\hat{\rho}^{(\mathrm{H})}_{\mathbf{G}}, \hat{H}^{(\mathrm{H})}] \hat{P}^{(\mathrm{H})}(t) \right\} \nonumber\\
L000642	    &&= \frac{1}{i \hbar} \mathrm{Tr} \left\{ \hat{\rho}^{(\mathrm{H})}_{\mathbf{G}} [\hat{H}^{(\mathrm{H})}, \hat{P}^{(\mathrm{H})}(t)] \right\} \nonumber\\
L000643	    &&= \frac{1}{i \hbar} \mathrm{Tr} \left\{ \hat{\rho}_{\mathbf{G}} [\hat{H}, \hat{P}(t)] \right\} \nonumber\\
L000644	    &&= \mathrm{Tr} \left\{ \hat{\rho}_{\mathbf{G}} \frac{\mathrm{d}}{\mathrm{d} t} \hat{P}(t) \right\},
L000645	\end{eqnarray}
L000646	where:
L000647	\begin{itemize}
L000648	    \item The second line follows from the Heisenberg equation of motion.
L000649	    \item The third line uses the cyclic property of the trace: $\mathrm{Tr}\{[A,B]C\} = \mathrm{Tr}\{A[B,C]\}$.
L000650	    \item The fourth line switches back to the Schr\"{o}dinger picture, since the trace is invariant under picture change.
L000651	    \item The final line applies the Liouville–von Neumann equation [Eq.~(\ref{eq:liouville_von_neumann})].
L000652	\end{itemize}
L000653	We now focus on the second-order contribution to the density operator, $\hat{P}^{(2)}(t)$. This component is related to its frequency-domain representation by:
L000654	$\hat{P}^{(2)}(t) = \int \left[ \mathrm{d}\omega \right] e^{-i\omega t + 2 \eta t} \hat{P}^{(2)}(\omega)$.
L000655	Taking the time derivative in Eq.~(\ref{eq:trace_trick}) and setting $\omega=0$ then yields
L000656	\footnote{The precise form of the time derivative of $\hat{P}^{(2)}(t)$ depends on how the relaxation parameter $\uptau$ is introduced. As a result, the
L000657	coefficient $2\eta$ in Eq.~(\ref{eq:ptrho_sm}) may not be universal.}:
L000658	\begin{equation}
L000659	\label{eq:ptrho_sm}
L000660	    \left\langle \partial_t \hat{\rho}^{(\mathrm{H})}_{\mathbf{G}} \right\rangle =
L000661	    2\eta\,\mathrm{Tr} \left\{ \hat{\rho}_{\mathbf{G}} \hat{P}^{(2)}(t) \right\} =
L000662	    2 \eta \, \Delta\rho_{\mathbf{G}}.
L000663	\end{equation}
L000664	Substituting this result into Eq.~(\ref{eq:CE_expectation}), we obtain:
L000665	\begin{equation}
L000666	    2 \eta \, \Delta\rho_{\mathbf{G}} + i \mathbf{G} \cdot \left\langle \hat{\mathbf{j}}^{(\mathrm{H})}_{\mathbf{G}} \right\rangle = 0.
L000667	\end{equation}
L000668	Finally, expressing $\Delta\rho_{\mathbf{G}}$ and $\left\langle \hat{\mathbf{j}}^{(\mathrm{H})}_{\mathbf{G}} \right\rangle$ in terms of
L000669	the response coefficients $\zeta^{\alpha_1\alpha_2}(\mathbf{G};\omega_0)$ and $\sigma^{\beta \alpha_1\alpha_2}(\mathbf{G};\omega_0)$,
L000670	we recover Eq.~(\ref{eq:CE_coef_sm}).
L000671	
L000672	\section{\label{sec:continuum_model}Continuum Model Hamiltonian of $\text{tMoTe}_{\text{2}}$}
L000673	
L000674	The continuum model Hamiltonian of $\text{tMoTe}_{\text{2}}$ at twist angle $\theta$, for the $+\mathbf{K}$ valley and spin-up electrons, is given by the
L000675	following $4\times 4$ matrix \Scite{wu2019topological}:
L000676	\begin{equation}
L000677	\mathcal{H}_{\uparrow}(\mathbf{k}, \mathbf{r})=\left(\begin{array}{cc}
L000678	h_b(\mathbf{k}, \mathbf{r}) & T(\mathbf{r}) \\
L000679	T^{\dagger}(\mathbf{r})     & h_t(\mathbf{k}, \mathbf{r})
L000680	\end{array}\right),
L000681	\end{equation}
L000682	where $h_l(\mathbf{k}, \mathbf{r})$ (with $l=+1$ for the bottom layer and $l=-1$ for the top layer) describes the intralayer Hamiltonian, and $T(\mathbf{r})$ encodes the interlayer coupling. Here, $\mathbf{k} \equiv -i\nabla_{\mathbf{r}}$ acts as an operator on the real-space coordinate $\mathbf{r}$. The
L000683	corresponding Hamiltonian for the $-\mathbf{K}$ valley and spin-down electrons can be obtained via time-reversal symmetry.
L000684	
L000685	The intralayer Hamiltonians take the form:
L000686	\begin{equation}
L000687	h_l(\mathbf{k}, \mathbf{r}) = \left(\begin{array}{cc}
L000688	\Delta_g + \Delta_{l,c}(\mathbf{r}) & 0 \\
L000689	0                                   & \Delta_{l,v}(\mathbf{r})
L000690	\end{array}\right) + e^{-i l \frac{\theta}{4} \xi_z} \left[ \hbar v_F (\mathbf{k} - \boldsymbol{\kappa}_l) \cdot \boldsymbol{\xi} \right] e^{i l \frac{\theta}{4} \xi_z}
L000691	,
L000692	\end{equation}
L000693	where the subscripts $c$ and $v$ label the conduction and valence bands of the monolayer, respectively. The vector $\boldsymbol{\xi}$ contains the Pauli matrices acting
L000694	in the band subspace, and $\boldsymbol{\kappa}_l$ denotes the $+\mathbf{K}$ point of monolayer $\text{MoTe}_{\text{2}}$ in layer $l$, as defiend in
L000695	Fig.~\hyperref[fig:tMoTe2]{2(c)} of the main text.
L000696	The spatially modulated potentials $\Delta_{l,\nu}(\mathbf{r})$ (with $\nu=c,\,v$) are given by:
L000697	\begin{equation}
L000698	    \Delta_{l,\nu}(\mathbf{r}) = 2 V_{\nu} \sum_{i=1,3,5} \mathrm{cos}(\mathbf{G}_i \cdot \mathbf{r} + l \psi_{\nu}),
L000699	\end{equation}
L000700	with $\mathbf{G}_i$ denoting the moir\'e reciprocal lattice vectors defined in Fig.~\hyperref[fig:tMoTe2]{2(c)} of the main text.
L000701	
L000702	The interlayer coupling matrix $T(\mathbf{r})$ is expressed as:
L000703	\begin{equation}
L000704	    T(\mathbf{r}) = T_0 + T_1 e^{i \mathbf{G}_5 \cdot \mathbf{r}} + T_2 e^{i \mathbf{G}_6 \cdot \mathbf{r}},
L000705	\end{equation}
L000706	with the matrices $T_0$, $T_1$, $T_2$ defined as:
L000707	\begin{equation}
L000708	T_0 = \left(\begin{array}{cc}
L000709	w_{c}  & w_{cv} \\
L000710	w_{vc} & w_{v}
L000711	\end{array}\right),\;\;\;
L000712	T_1 = \left(\begin{array}{cc}
L000713	w_{c}              & w_{cv} e^{-i2\pi/3} \\
L000714	w_{vc} e^{i2\pi/3} & w_{v}
L000715	\end{array}\right),\;\;\;
L000716	T_2 = \left(\begin{array}{cc}
L000717	w_{c}               & w_{cv} e^{i2\pi/3} \\
L000718	w_{vc} e^{-i2\pi/3} & w_{v}
L000719	\end{array}\right).
L000720	\end{equation}
L000721	The parameter values used in this model are:
L000722	\begin{itemize}
L000723	    \item $\Delta_g=1.1\, \text{eV}$,
L000724	    \item $v_F = 0.4\times10^6 \, \text{m/s}$,
L000725	    \item $(V_v, \psi_v, w_v) = (8\, \text{meV}, -89.6^\circ, -8.5\, \text{meV})$,
L000726	    \item $(V_c, \psi_c, w_c) = (5.97\, \text{meV}, -87.9^\circ, -2\, \text{meV})$,
L000727	    \item $w_{cv} = w_{vc}^* = 15.3\, \text{meV}$.
L000728	\end{itemize}
L000729	The monolayer lattice constant of $\text{MoTe}_{\text{2}}$ is taken to be $3.472$~\AA.
L000730	
L000731	\section{\label{sec:poisson}Technical Details for Generating Figs.~\hyperref[fig:patterns]{4(c)} and~\hyperref[fig:patterns]{4(d)}}
L000732	
L000733	In this section, we outline the procedure used to compute the electrostatic potential $U(\mathbf{r})$ generated by the redistributed charge in the $\text{tMoTe}_{\text{2}}$ system, which is used to produce Figs.~\hyperref[fig:patterns]{4(c)} and~\hyperref[fig:patterns]{4(d)}.
L000734	
L000735	The system is modeled in a Cartesian coordinate system. The top layer of $\text{MoTe}_{\text{2}}$, located at $z=0$,
L000736	carries a surface charge density $\Delta\rho_{\mathrm{2D}}^t(x,y)$, while the bottom layer, located at $z=-d_0$, carries a surface charge density
L000737	$\Delta\rho_{\mathrm{2D}}^b(x,y)$, where $d_0$ is the interlayer separation. An adjacent layered material is placed at $z=d_1>0$, and our objective is to
L000738	determine the electrostatic potential $U(x,y,z=d_1)$. For the numerical results shown in the main text, we use $d_0 = 6.9$~\AA~and $d_1 = 10$~\AA.
L000739	
L000740	The electrostatic potential $U(x,y,z)$ satisfies the Poisson equation:
L000741	\begin{equation}
L000742	\label{eq:poisson}
L000743	    \nabla^2 U(x,y,z) = -\frac{1}{\varepsilon_0}\left[ \Delta\rho_{\mathrm{2D}}^t(x,y) \delta(z) + \Delta\rho_{\mathrm{2D}}^b(x,y) \delta(z+d_0) \right],
L000744	\end{equation}
L000745	where $\varepsilon_0$ is the vacuum permittivity, and $\delta(z)$ represents the Dirac delta function. To compute the source term on the right-hand side
L000746	of Eq.~(\ref{eq:poisson}), which includes $\Delta\rho_{\mathrm{2D}}^t(x,y)$ and $\Delta\rho_{\mathrm{2D}}^b(x,y)$, we evaluate the layer-resolved charge response
L000747	coefficients $\zeta^{\alpha_1 \alpha_2}(\mathbf{G}, l; \omega_0)$. These coefficients are obtained
L000748	by replacing the original wavefunctions $\left| u_{\mathbf{k} s} \right\rangle$ with the layer-projected wavefunctions
L000749	$\left| u^{l}_{\mathbf{k} s} \right\rangle$ in the form factor $F^{\mathbf{G}}_{\mathbf{k} s s^{\prime}}$ in Eq.~(\ref{eq:zeta_expression}).
L000750	
L000751	To solve Eq.~(\ref{eq:poisson}), we apply a Fourier transform:
L000752	\begin{equation}
L000753	\label{eq:poisson_fourier}
L000754	    U(x,y,z) = \sum_{\mathbf{G}} \int \frac{\mathrm{d}k}{2\pi}\, u_\mathbf{G}(k) \, e^{i\mathbf{G}\cdot \mathbf{r}_{\mathrm{2D}}+ikz},
L000755	\end{equation}
L000756	where the sum is over moir\'e reciprocal lattice vectors $\mathbf{G}$, and $\mathbf{r}_{\mathrm{2D}}=(x,y)$. Substituting Eq.~(\ref{eq:poisson_fourier})
L000757	into Eq.~(\ref{eq:poisson}) transforms the differential equation into an algebraic equation for $u_\mathbf{G}(k)$, which can be easily solved:
L000758	\begin{equation}
L000759	\label{eq:fourier_sol}
L000760	    u_\mathbf{G}(k) = \frac{\Delta\rho_{\mathbf{G}}^t + \Delta\rho_{\mathbf{G}}^b \, e^{ikd_0}}{\varepsilon_0 \,(|\mathbf{G}|^2+k^2)}.
L000761	\end{equation}
L000762	Inserting Eq.~(\ref{eq:fourier_sol}) into Eq.~(\ref{eq:poisson_fourier}) and performing the $k$-integral yields the electrostatic potential at $z=d_1$:
L000763	\begin{equation}
L000764	\label{eq:poisson_sol}
L000765	    U(x,y,z=d_1) = \sum_{\mathbf{G}} u_{\mathbf{G}} \, e^{i\mathbf{G}\cdot \mathbf{r}_{\mathrm{2D}}},
L000766	\end{equation}
L000767	with coefficients
L000768	\begin{equation}
L000769	\label{eq:potential_fourier}
L000770	    u_{\mathbf{G}} = \frac{e^{-|\mathbf{G}| d_1}}{2 \varepsilon_0 |\mathbf{G}|} (\Delta\rho_{\mathbf{G}}^t + \Delta\rho_{\mathbf{G}}^b \, e^{-|\mathbf{G}| d_0}).
L000771	\end{equation}
L000772	The numerical results obtained from Eqs.~(\ref{eq:poisson_sol}) and~(\ref{eq:potential_fourier}) are then used to generate the electrostatic potential
L000773	distributions shown in Figs.~\hyperref[fig:patterns]{4(c)} and~\hyperref[fig:patterns]{4(d)} of the main text.
L000774	
